WITH base AS (SELECT * FROM stores WHERE region != 'East' AND opened_date BETWEEN '2024-10-01' AND '2025-06-01'), opened_month_summary AS (SELECT DATE_TRUNC('MONTH', opened_date) AS opened_month, city, SUM(CASE WHEN city = 'Tokyo' THEN 1 ELSE 0 END) AS tokyo_count, COUNT(CASE WHEN region = 'South' THEN 1 END) AS south_count FROM base GROUP BY DATE_TRUNC('MONTH', opened_date), city) SELECT * FROM opened_month_summary WHERE tokyo_count < 79 ORDER BY tokyo_count, city, opened_month LIMIT 10;
